/// <summary>
///    AVA <c>RelationsTabPagePageActivatedGlobal</c> method.
/// </summary>
/// <param name="control">
///    <c>FormControl</c> as type
/// </param>
/// <param name="e">
///    <c>FormControlEventArgs</c> as type
/// </param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'), 
    FormControlEventHandler(formcontrolstr(smmBusRelTable, RelationsTabPage), FormControlEventType::PageActivated)  ]
public static void RelationsTabPagePageActivatedGlobal(FormControl control, FormControlEventArgs e)
{
    FormRun         form;
    FormGridControl relationsGrid;
    boolean         BPCheck;

    if(e)
    {
        BPCheck = true;
    }

    form            = control.formRun();
    relationsGrid   = form.design().controlName(formcontrolstr(smmBusRelTable, RelationsGrid));

    //form.refreshHeaderTabPage(); // method does not exist
    relationsGrid.setFocus();
}

/// <summary>
///    AVA <c>DirRelationshipViewModifiedGlobal</c> method.
/// </summary>
/// <param name="control">
///    <c>FormControl</c> as type
/// </param>
/// <param name="e">
///    <c>FormControlEventArgs</c> as type
/// </param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formcontrolstr(smmBusRelTable, DirRelationshipView), FormControlEventType::Modified)]
public static void DirRelationshipViewModifiedGlobal(FormControl control, FormControlEventArgs e)
{
    FormRun             form;
    FormDesign          design;
    FormGroupControl    childToParentGroup;
    FormGroupControl    parentToChildGroup;
    FormComboBoxControl dirRelationshipView;

    form                = control.formRun();
    design              = form.design();
    childToParentGroup  = design.controlName(formcontrolstr(smmBusRelTable, ChildToParentGroup));
    parentToChildGroup  = design.controlName(formcontrolstr(smmBusRelTable, ParentToChildGroup));
    dirRelationshipView = control as FormComboBoxControl;

    childToParentGroup.visible(dirRelationshipView.selection() == DirRelationshipView::ChildToParent);
    parentToChildGroup.visible(dirRelationshipView.selection() == DirRelationshipView::ParentToChild);
}

